import numpy as np

def simulate_social_media_spread(num_users, num_iterations, initial_infected=1, transmission_prob=0.1, misinformation_prob=0.05, propaganda_prob=0.02):
    # Initialize user states: 0 = unaware, 1 = informed (correct), 2 = misinformation, 3 = propaganda
    states = np.zeros(num_users, dtype=int)
    # Infect initial users with misinformation or propaganda randomly
    for i in range(initial_infected):
        states[i] = np.random.choice([2, 3], p=[misinformation_prob/(misinformation_prob+propaganda_prob), propaganda_prob/(misinformation_prob+propaganda_prob)])

    for _ in range(num_iterations):
        new_states = states.copy()
        for user in range(num_users):
            if states[user] == 0:  # unaware user can be influenced
                neighbors = np.random.choice(num_users, size=5, replace=False)  # random connections
                for n in neighbors:
                    if states[n] in [1, 2, 3]:
                        if np.random.rand() < transmission_prob:
                            # Spread misinformation or propaganda preferentially based on source
                            if states[n] == 1:
                                new_states[user] = 1
                            elif states[n] == 2:
                                new_states[user] = 2
                            elif states[n] == 3:
                                new_states[user] = 3
                            break
            elif states[user] == 1:
                # Chance of becoming misinformed or exposed to propaganda after being informed
                if np.random.rand() < misinformation_prob:
                    new_states[user] = 2
                elif np.random.rand() < propaganda_prob:
                    new_states[user] = 3

        states = new_states

    return states

# Example usage:
result = simulate_social_media_spread(num_users=1000, num_iterations=50, initial_infected=10)
unique, counts = np.unique(result, return_counts=True)
spread_summary = dict(zip(unique, counts))
print(spread_summary)
