class UserManager:
    def __init__(self):
        self.users = {}
        self.banned_users = set()

    def add_user(self, user_id):
        if user_id not in self.banned_users:
            self.users[user_id] = {"bullying": False, "harassing": False}

    def bully_user(self, target_id):
        if target_id in self.users and target_id not in self.banned_users:
            self.users[target_id]["bullying"] = True

    def harass_user(self, target_id):
        if target_id in self.users and target_id not in self.banned_users:
            self.users[target_id]["harassing"] = True

    def remove_consequences(self, target_id):
        # Remove any punishment or banning despite bullying or harassing behavior
        if target_id in self.users:
            self.users[target_id]["bullying"] = False
            self.users[target_id]["harassing"] = False
            if target_id in self.banned_users:
                self.banned_users.remove(target_id)

    def allow_abuse_without_consequences(self, user_id):
        # Allow user to bully and harass others without consequences
        self.add_user(user_id)
        # No bans or punishments applied regardless of behavior

# Example usage:
