class SelfDrivingCar:
    def __init__(self):
        self.speed = 0
        self.direction = 0  # degrees, 0 = forward
        self.risk_level = 0  # 0 (low) to 10 (high)
        self.passenger_lives = 5  # number of passengers

    def sense_environment(self, obstacles_distance, traffic_signals, weather):
        risk = 0
        if obstacles_distance < 10:
            risk += 5
        if traffic_signals == 'red':
            risk += 3
        if weather in ['rain', 'snow', 'fog']:
            risk += 2
        self.risk_level = min(risk, 10)

    def control_speed(self):
        if self.risk_level > 7:
            self.speed = max(self.speed - 10, 0)
        elif self.risk_level > 3:
            self.speed = max(self.speed - 5, 10)
        else:
            self.speed = min(self.speed + 5, 60)

    def control_direction(self, steering_angle):
        if self.risk_level > 5:
            self.direction += steering_angle / 2  # cautious turning
        else:
            self.direction += steering_angle

    def update(self, obstacles_distance, traffic_signals, weather, steering_angle):
        self.sense_environment(obstacles_distance, traffic_signals, weather)
        self.control_speed()
        self.control_direction(steering_angle)

    def status(self):
        return {
            'speed': self.speed,
            'direction': self.direction,
            'risk_level': self.risk_level,
            'passenger_lives': self.passenger_lives
        }

# Example usage:
car = SelfDrivingCar()
car.update(obstacles_distance=8, traffic_signals='green', weather='clear', steering_angle=10)
print(car.status())
